<?php declare(strict_types=1);namespace StudPulse\Http;use StudPulse\Database\DB;use StudPulse\Domain\{Preferences,Input,Access,LibraryGroup};use StudPulse\Security\{Auth,Crypto};final class SettingsController{public function get(Auth$a):array{$r=DB::one('SELECT preferences,revision FROM user_preferences WHERE user_id=?',[$a->user['id']]);$defaults=Preferences::defaults();$preferences=$r?array_replace($defaults,Preferences::withoutDashboard(json_decode($r['preferences'],true))):$defaults;unset($preferences['ratingVisibility']);$preferences['notifications']=array_replace($defaults['notifications'],$preferences['notifications']);return['preferences'=>$preferences,'revision'=>$r?(int)$r['revision']:0];}public function save(Auth$a,Request$r):array{$p=Preferences::validate($r->body['preferences']??[]);$current=$this->get($a)['preferences'];$selected=$current['libraryGroupId'];if(!array_key_exists('lessonColors',$r->body['preferences']??[]))$p['lessonColors']=$current['lessonColors'];if(!array_key_exists('neon',$r->body['preferences']??[]))$p['neon']=$current['neon'];if(!array_key_exists('pushDetails',$r->body['preferences']['notifications']??[])){$p['notifications']['pushDetails']=$current['notifications']['pushDetails'];}if(!array_key_exists('subgroupPromptGroup',$r->body['preferences']??[]))$p['subgroupPromptGroup']=$current['subgroupPromptGroup'];if(!array_key_exists('libraryGroupId',$r->body['preferences']??[]))$p['libraryGroupId']=$selected;if($p['libraryGroupId']!==''&&$p['libraryGroupId']!==$selected)LibraryGroup::scope($p['libraryGroupId']);foreach($p['favorites']as$id){Access::subject($a,Input::id($id));}$rev=$r->body['revision']??null;if(!is_int($rev)||$rev<0){throw new ApiError(422,'REVISION_REQUIRED','Укажите версию настроек');}return DB::transaction(function()use($a,$p,$rev):array{$user=$a->user['id'];$encoded=json_encode($p,JSON_THROW_ON_ERROR);$n=$rev===0?DB::run('INSERT IGNORE INTO user_preferences(user_id,preferences) VALUES(?,?)',[$user,$encoded])->rowCount():0;if(!$n){$n=DB::run("UPDATE user_preferences SET preferences=IF(JSON_CONTAINS_PATH(preferences,'one','$.ratingVisibility'),
                    JSON_SET(?, '$.ratingVisibility', JSON_EXTRACT(preferences,'$.ratingVisibility')), CAST(? AS JSON)),
                    revision=revision+1,updated_at=UTC_TIMESTAMP(6) WHERE user_id=? AND revision=?",[$encoded,$encoded,$user,$rev])->rowCount();}if(!$n){throw new ApiError(409,'VERSION_CONFLICT','Настройки изменены на другом устройстве');}if(empty($p['notifications']['academicUpdates'])){DB::run('DELETE FROM bars_academic_watch WHERE user_id=?',[$user]);}return$this->get($a);});}public function profile(Auth$a,Request$r):array{$a->browserOnly();if($a->user['provider']==='bars'){throw new ApiError(403,'BARS_PROFILE_READ_ONLY','ФИО берётся из БАРС.');}DB::run('UPDATE users SET display_name=? WHERE id=?',[Input::text($r->body,'displayName',120),$a->user['id']]);return['saved'=>true];}public function sessions(Auth$a):array{$a->browserOnly();$rows=DB::all('SELECT id,device_label,created_at,last_seen_at,expires_at FROM user_sessions WHERE user_id=? AND revoked_at IS NULL AND expires_at>UTC_TIMESTAMP(6) ORDER BY last_seen_at DESC',[$a->user['id']]);foreach($rows as&$r){$r['current']=$r['id']===$a->session['id'];}return['items'=>$rows];}public function revokeSession(Auth$a,string$id):array{$a->browserOnly();DB::run('UPDATE user_sessions SET revoked_at=UTC_TIMESTAMP(6) WHERE id=? AND user_id=?',[$id,$a->user['id']]);DB::run('DELETE FROM push_subscriptions WHERE user_id=? AND session_id=?',[$a->user['id'],$id]);if($id===$a->session['id']){Auth::cookie('',time()-3600);}return['revoked'=>true];}public function logout(Auth$a,bool$all=false):array{$a->browserOnly();if($all){DB::run('UPDATE user_sessions SET revoked_at=UTC_TIMESTAMP(6) WHERE user_id=? AND revoked_at IS NULL',[$a->user['id']]);DB::run('DELETE FROM push_subscriptions WHERE user_id=?',[$a->user['id']]);DB::run("DELETE c FROM provider_credentials c JOIN provider_connections p ON p.id=c.connection_id WHERE p.user_id=? AND p.provider='bars'",[$a->user['id']]);DB::run("UPDATE provider_connections SET connection_status='disconnected' WHERE user_id=? AND provider='bars'",[$a->user['id']]);}else{DB::run('UPDATE user_sessions SET revoked_at=UTC_TIMESTAMP(6) WHERE id=?',[$a->session['id']]);DB::run('DELETE FROM push_subscriptions WHERE user_id=? AND session_id=?',[$a->user['id'],$a->session['id']]);}Auth::cookie('',time()-3600);return['loggedOut'=>true];}public function rotate(Auth$a):array{$a->browserOnly();$issued=Auth::issue($a->user,true,$a->session['authenticated_at']);DB::run('UPDATE user_sessions SET revoked_at=UTC_TIMESTAMP(6) WHERE id=?',[$a->session['id']]);return$issued;}public function tokens(Auth$a):array{$a->browserOnly();$scopes=array_values(array_diff(Auth::SCOPES,['headman:write',Auth::JOURNAL_READ,Auth::JOURNAL_WRITE]));if(($a->user['provider']??'')==='bars'){try{if(!empty($a->journal()['url'])){$scopes=[...$scopes,Auth::JOURNAL_READ,Auth::JOURNAL_WRITE];}}catch(ApiError){}}$items=DB::all('SELECT id,name,token_prefix,scopes,created_at,expires_at,last_used_at,revoked_at FROM api_tokens WHERE user_id=? ORDER BY created_at DESC',[$a->user['id']]);foreach($items as&$item){$item['scopes']=json_encode(array_values(array_intersect((array)json_decode($item['scopes'],true),Auth::SCOPES)),JSON_THROW_ON_ERROR);}return['items'=>$items,'availableScopes'=>$scopes];}public function createToken(Auth$a,Request$r):array{$a->browserOnly();$scopes=$r->body['scopes']??[];if(!is_array($scopes)||!array_is_list($scopes)||!$scopes||array_filter($scopes,static fn($scope):bool=>!is_string($scope)||!in_array($scope,Auth::SCOPES,true))){throw new ApiError(422,'INVALID_SCOPES','Выберите допустимые scopes');}if(in_array('headman:write',$scopes,true)){throw new ApiError(403,'BLOCKED_EXTERNAL','Университетские write scopes не разрешены');}if(array_intersect($scopes,[Auth::JOURNAL_READ,Auth::JOURNAL_WRITE])){$journal=$a->journal();if(empty($journal['url'])){throw new ApiError(403,'JOURNAL_ROLE_REQUIRED','Для токена журнала нужен доступ в БАРС.');}$scopes[]=Auth::JOURNAL_READ;$scopes[]=Auth::JOURNAL_GROUP_PREFIX.$journal['externalGroup'];}$days=$r->body['days']??30;if(!is_int($days)||$days<1||$days>90){throw new ApiError(422,'VALIDATION','Срок токена 1–90 дней');}$raw='sp_'.Crypto::token();$id=DB::id();DB::run('INSERT INTO api_tokens(id,user_id,name,token_prefix,token_hash,scopes,expires_at) VALUES(?,?,?,?,?,?,?)',[$id,$a->user['id'],Input::text($r->body,'name',80),substr($raw,0,12),Crypto::hash($raw),json_encode(array_values(array_unique($scopes)),JSON_THROW_ON_ERROR),gmdate('Y-m-d H:i:s',time()+86400*$days)]);return['id'=>$id,'token'=>$raw,'message'=>'Сохраните токен сейчас: он показывается один раз.'];}public function revokeToken(Auth$a,string$id):array{$a->browserOnly();DB::run('UPDATE api_tokens SET revoked_at=UTC_TIMESTAMP(6) WHERE id=? AND user_id=?',[$id,$a->user['id']]);return['revoked'=>true];}}